enum Command { Suspend(String), Resume(String), Snapshot(oneshot::Sender<Status>) }

let (cmd_tx, mut cmd_rx) = mpsc::channel::<Command>(64);
let (config_tx, mut config_rx) = watch::channel(Config::default());
let shutdown = CancellationToken::new();

tokio::spawn(async move {
    loop {
        tokio::select! {
            Some(cmd) = cmd_rx.recv() => apply(cmd).await,
            _ = shutdown.cancelled() => break,                 // stop: child tokens cancel too
            _ = config_rx.changed() => reconfigure(config_rx.borrow().clone()).await,
        }
    }
});

