enum Control { Suspend, Resume, Snapshot(RpcReplyPort<Status>) }

impl Actor for Adapter {
    type Msg = Control;
    type State = AdapterState;
    type Arguments = ();

    async fn handle(&self, _myself: ActorRef<Self::Msg>, msg: Control, st: &mut Self::State)
        -> Result<(), ActorProcessingErr> {
        match msg {
            Control::Suspend => st.paused = true,
            Control::Resume => st.paused = false,
            Control::Snapshot(reply) => { let _ = reply.send(st.snapshot()); }
        }
        Ok(())
    }
}
// actor.stop(None) is graceful; Signal::Kill interrupts immediately and skips cleanup
